+package com.example;
+
+import org.springframework.stereotype.Component;
+
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Keeps messages for the lifetime of this application.  Views are recreated on
+ * navigation, so the messages deliberately live outside a ContactView.
+ */
+@Component
+public class MessageStore {
+
+    private final List<SentMessage> messages = new ArrayList<>();
+
+    public synchronized void add(SentMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<SentMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
