+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validatesAndSendsMessages() {
+        navigate(ContactView.class);
+        Button send = $(Button.class).withText("Send").single();
+
+        test(send).click();
+        assertEquals("Name is required", $(TextField.class).withLabel("Name").single().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number",
+                $(EmailField.class).withLabel("Email").single().getErrorMessage());
+        assertEquals("Message is required", $(TextArea.class).withLabel("Message").single().getErrorMessage());
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Ada");
+        test($(EmailField.class).withLabel("Email").single()).setValue("ada@example.com");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Hello");
+        test(send).click();
+
+        Grid<?> grid = $(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Ada", test(grid).getCellText(0, 0));
+        assertEquals("Hello", test(grid).getCellText(0, 1));
+        assertFalse(send.isEnabled());
+        assertTrue($(Notification.class).exists());
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        assertEquals("", name.getValue());
+        test(name).setValue("Grace");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void asksBeforeLeavingAChangedForm() {
+        navigate(ContactView.class);
+        test($(TextField.class).withLabel("Name").single()).setValue("Ada");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        assertTrue($(Dialog.class).exists());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
